#pragma once
#include <juce_core/juce_core.h>
#include <vector>

// Factory library (resources/presets.json, generated by tools/gen_presets.py).
struct PresetModule
{
    int slot = 0;                  // 0..4 = A..E
    juce::String model;            // instrument (matches a Model name)
    juce::NamedValueSet values;    // module suffix -> value (number or choice name)
};

struct Preset
{
    juce::String name, original, synth, genre, song, artist, category, notes, decade;
    int year = 0;
    std::vector<PresetModule> modules;
    juce::NamedValueSet globals;   // g_* id -> value
    juce::String sections() const; // e.g. "A", "A+B"
};

struct Model
{
    juce::String name, skin, maker;
    bool digital = false;
    int year = 0;
};

class PresetLibrary
{
public:
    static const PresetLibrary& get();
    const std::vector<Preset>& all() const { return presets; }
    const std::vector<Model>& models() const { return modelList; }
    int modelIndex (const juce::String& name) const;
    const Model* model (int index) const { return juce::isPositiveAndBelow (index, (int) modelList.size()) ? &modelList[(size_t) index] : nullptr; }
    juce::StringArray genres, decades;
private:
    PresetLibrary();
    std::vector<Preset> presets;
    std::vector<Model> modelList;
};
